def pointer(lang,section,quote):
 return {'path':'paper/RH_PROPAGATION_REPORT_'+lang+'.html','page':None,'start_line':2,'end_line':2,'label':'#'+section,'quote':quote}
def issue(n,category,section,en,ko,diagnosis,impact,action):
 ps=[pointer('EN',section,en)]
 if ko:ps.append(pointer('KO',section,ko))
 return {'issue_id':'READER-%02d'%n,'case_id':CID,'category':category,'locations':ps,'supporting_passages':ps,'issue':diagnosis,'reader_impact':impact,'suggested_action':action,'source_evidence':[]}
